function item(id, type, puzzle, solution, targetTechnique, allowedTechniques, verification, source, startLibrary = "", options = {}) {
  const record = {
    id,
    type,
    puzzle,
    solution,
    targetTechnique,
    allowedTechniques,
    source,
    verified: true,
    verification: Object.freeze(verification),
  };
  if (startLibrary) record.startLibrary = startLibrary;
  if (options?.targetFirst === true) record.targetFirst = true;
  if (options?.targetFilter) record.targetFilter = String(options.targetFilter);
  return Object.freeze(record);
}

