export function campaignChapterById(id) {
  return CAMPAIGN_CHAPTERS.find((chapter) => chapter.id === id) || null;
}

export function campaignLessonById(chapterId, lessonId) {
  return campaignChapterById(chapterId)?.lessons?.find((lesson) => lesson.id === lessonId) || null;
}

export function campaignItemById(chapterId, lessonId, itemId) {
  const chapter = campaignChapterById(chapterId);
  if (!chapter) return null;
  if (lessonId === "__boss__") return chapter.boss?.item?.id === itemId ? chapter.boss.item : null;
  return campaignLessonById(chapterId, lessonId)?.items?.find((entry) => entry.id === itemId) || null;
}
